compliant.code:
from typing import List

def process_items(items: List[str]) -> None:
    for item in items:
        print(item.upper())

# Correct: passing a list of strings
process_items(['apple', 'banana', 'cherry'])

from typing import Union

def format_value(value: Union[str, int]) -> str:
    return str(value)

# Correct: can pass either string or integer
format_value('hello')
format_value(42)

noncompliant.code:
from typing import List

def process_items(items: List[str]) -> None:
    for item in items:
        print(item.upper())

# Incorrect: passing a list of integers
process_items([1, 2, 3])  # This will raise AttributeError at runtime
